alter policy staff_chart_identity on public.patients using(false); alter policy staff_chart_contacts on public.patient_contacts using(false); alter policy staff_chart_consents on public.consent_records using(false);
do $$ declare pol record; begin for pol in select schemaname,tablename,policyname from pg_policies where schemaname='public' and tablename in ('care_team_assignments','patient_site_enrollments','staff_site_assignments','restricted_record_flags','restricted_record_opens','advocates','advocate_links','referrals','referral_codes','referral_status_updates','referral_outreach_log','signup_sessions','signup_attempts','signup_safety_scans','identity_review_items','account_support_items','website_inbox_items','intake_checklists','intake_form_status','intake_packet_needs','pre_chart_triage','first_visit_handoffs','staging_imports','staging_rows','packet_documents','on_call_shifts') and policyname<>'closed_default' loop execute format('alter policy %I on public.%I using(false)',pol.policyname,pol.tablename); end loop; end $$;
revoke execute on function public.phase2_packet_documents(uuid),public.advocate_view_identity(uuid),app.packet_documents_view(uuid),app.advocate_view_identity(uuid),app.resolve_crisis_owner(uuid,uuid,text,timestamptz) from authenticated;